import {
  DatePicker,
  DatePickerCalendar,
  DatePickerContent,
  DatePickerInput,
} from "@/registry/erbium/ui/date-picker";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";

const Example = () => (
  <Field className="w-64" disabled>
    <FieldLabel htmlFor="date-picker-disabled">Start date</FieldLabel>
    <DatePicker disabled defaultValue={new Date(2026, 0, 12)}>
      <DatePickerInput id="date-picker-disabled" />
      <DatePickerContent>
        <DatePickerCalendar />
      </DatePickerContent>
    </DatePicker>
  </Field>
);

export default Example;
